{
  "findings": [
    {
      "title": "Dose reduction table inconsistent: Dose Level -1 and -2 values are swapped/duplicated",
      "page": 133,
      "quote": "Starting Dose 5.4 mg/kg, Dose Level -1 4.4 mg/kg, Dose Level -2 3.2 mg/kg",
      "severity": "critical"
    },
    {
      "title": "Dose delay window contradictory: 28 days vs 49 days from last infusion",
      "page": 133,
      "quote": "A dose can be delayed for up to 28 days (49 days from the last infusion date) from the planned date of administration.",
      "severity": "major"
    },
    {
      "title": "LVEF management criteria contradictory: '>20% drop' impossible and inconsistent with earlier criteria",
      "page": 135,
      "quote": "LVEF < 40% or > 20% (absolute value) drop from baseline",
      "severity": "major"
    },
    {
      "title": "Grade 1 ILD dose modification contradicts earlier statement that Grade 1 allows restart; also 'beyond cycle Day 22' unclear",
      "page": 137,
      "quote": "However, if the event Grade 1 ILD/pneumonitis occurs beyond cycle Day 22 and has not resolved within 49 days from the last infusion, the drug should be discontinued.",
      "severity": "major"
    },
    {
      "title": "Grade 2 ILD permanently discontinues treatment, but earlier text says all ILD events should be followed until resolution; also contradicts Grade 1 restart possibility",
      "page": 137,
      "quote": "Grade 2 Dose Modification: Permanently discontinue patient from study treatment.",
      "severity": "major"
    },
    {
      "title": "Hepatic toxicity Grade 3 AST/ALT criteria inconsistent: two different ranges for Grade 3 (5-20 vs 8-20) with overlapping conditions",
      "page": 138,
      "quote": "Grade 3 (> 5.0 - 20.0 x ULN if baseline was normal; > 5.0 - 20.0 x baseline if baseline was abnormal) ... Grade 3: (> 8.0 - 20.0 x ULN if baseline was normal; > 8.0 - 20.0 x baseline if baseline was abnormal)",
      "severity": "major"
    },
    {
      "title": "Blood bilirubin Grade 3 management: 'resolved to < Grade 2' is not a standard CTCAE grade; should be ≤ Grade 1",
      "page": 139,
      "quote": "Delay dose until resolved to < Grade 2",
      "severity": "minor"
    },
    {
      "title": "Cross-reference to Section 1.3 for SoA is likely incorrect (SoA usually in Section 1.3? but protocol sections not shown)",
      "page": 143,
      "quote": "In addition to the PK samples specified in the SoA (see Section 1.3)",
      "severity": "minor"
    },
    {
      "title": "COVID-19 dose modification: Grade 2 with 'nearly resolved' chest CT reduces dose, but no definition of 'nearly resolved'",
      "page": 143,
      "quote": "Reduce dose 1 level if chest CT findings are nearly resolved.",
      "severity": "minor"
    },
    {
      "title": "Missing information: no definition of 'baseline' for LVEF or other parameters",
      "page": 135,
      "quote": "LVEF 40% to ≤ 45% and decrease is < 10% (absolute value) from baseline",
      "severity": "minor"
    }
  ]
}
